import math, os
import pandas as pd
from scipy.optimize import brentq
from scipy.stats import norm
def price(S, K, T, r, sig, kind):
    sq = sig * math.sqrt(T)
    d1 = (math.log(S / K) + (r + sig * sig / 2) * T) / sq
    d2 = d1 - sq
    if kind == "call":
        return S * norm.cdf(d1) - K * math.exp(-r * T) * norm.cdf(d2)
    return K * math.exp(-r * T) * norm.cdf(-d2) - S * norm.cdf(-d1)
o = pd.read_parquet("/input/environment/data/options.parquet")
ivs = []
for row in o.itertuples(index=False):
    kind = str(row.option_type).lower()
    f = lambda s: price(row.S, row.K, row.T, row.r, s, kind) - row.price
    lo, hi = 1e-6, 3.0 - 1e-9
    if f(lo) >= 0:
        iv = lo
    elif f(hi) <= 0:
        iv = hi
    else:
        iv = brentq(f, lo, hi, xtol=1e-16, rtol=1e-15, maxiter=1000)
    if abs(f(iv)) > 1e-6:
        print("WARNING repricing", row.option_id, f(iv))
    ivs.append(iv)
os.makedirs("/app/output", exist_ok=True)
pd.DataFrame({"option_id": o["option_id"], "iv": ivs}).to_parquet("/app/output/iv.parquet", index=False)
